    "createdAt" timestamp with time zone NOT NULL,
    "updatedAt" timestamp with time zone NOT NULL,
    "userId" bigint,
    type character varying(255),
    key character varying(255),
    "workflowId" bigint
);


--
-- Name: workflowTasks_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

